discovery_port_probe.script:
 function(cidata, result, scanner, status, midServer, sensor) {
		var logger = new global.DiscoveryLogger(status);

		var certificateIngestion = new sn_disco_certmgmt.CertificateDiscoveryIngestion();

		var encodedPayload = scanner.contents.certificate_payload;
		if (encodedPayload == null) {
			logger.warn("Could not receive certificate chain on " + result.ip + ":" + scanner.port, 'Shazzam', sensor.getEccQueueId());
			return;
		}

		var decodedPayload = SNC.ProbePayloadTransportHelper.unpackTransportToStructured(encodedPayload, true, "UTF-8");
		if (decodedPayload == null) {
			logger.warn("Could not decode certificate chain on " + result.ip + ":" + scanner.port, 'Shazzam', sensor.getEccQueueId());
			return;
		}

		var insertedID = certificateIngestion.ingestCertificatesFromPortScan(
			status.sysID,
			result.ip,
			scanner.port,
			scanner.contents.dns_name,
			decodedPayload
		);

		if (gs.nil(insertedID))
			logger.warn("Was not able to insert a certificate history record on " + result.ip + ":" + scanner.port, 'Shazzam', sensor.getEccQueueId());

		var link = new global.RecordToHTML('sn_disco_certmgmt_certificate_history', insertedID, '${source}:${port}',  true);
		logger.info('[code]Captured certificate chain for ' + link.toString() + '[/code]', 'Shazzam', sensor.getEccQueueId());

 }
